19	// semanticSearchV4CellTimeout bounds each per-cell v4 query (token exchange +
20	// the query-serve call), mirroring codeSearchCellTimeout.
21	const semanticSearchV4CellTimeout = 30 * time.Second
22	
23	// semanticSearchControlPlaneTimeout bounds each control-plane discovery call
24	// (repo index / repo lookup) on the v4 path.
25	const semanticSearchControlPlaneTimeout = 10 * time.Second
26	
27	// semanticSearcher performs one semantic search. The command layer builds one
28	// per invocation (newSemanticSearcher) and every entry point — the one-shot
29	// command, the TUI's initial fetch, interactive re-searches, and pagination —
30	// calls through it, so all of them share one discovery cache.
31	type semanticSearcher func(ctx context.Context, cfg search.Config) (*search.Response, error)
32	
33	// newSemanticSearcher returns the semantic-search entry for this invocation: a
34	// v4 query-serve session (ENT-1055) that fans out across entire-api cells and
35	// caches control-plane discovery across calls.
36	func newSemanticSearcher(insecureHTTP bool) semanticSearcher {
37		s := &semanticSearchV4Session{insecureHTTP: insecureHTTP}
38		return s.search
39	}
40	
41	// loginHintErr maps auth.ErrNotLoggedIn to the standard login hint; other
42	// errors pass through unchanged.
43	func loginHintErr(err error) error {
44		if errors.Is(err, auth.ErrNotLoggedIn) {
45			return errors.New("not authenticated. Run 'entire login' to authenticate")
46		}
47		return err
48	}
49	
50	// semanticSearchV4Session holds per-invocation state for the v4 query-serve
51	// path. Control-plane discovery (the repo index, per-slug repo lookups, the
52	// cluster catalog) is stable for the life of one command, so it is resolved
53	// once and reused across TUI re-searches and pagination instead of paying
54	// several network round trips per keystroke-search. Identity tokens are NOT
55	// cached here — fanOutCells mints them per search (at most one per
56	// jurisdiction), which keeps expiry handling in the auth layer.
57	type semanticSearchV4Session struct {
58		insecureHTTP bool
59	
60		mu         sync.Mutex
61		coreClient *coreapi.Client
62		clusters   *cachedClusterClient
63		fullIndex  *coreapi.ListReposOutputBody        // unfiltered index, fetched at most once
64		slugRepos  map[string][]coreapi.RepoIndexEntry // per-filter exact-match lookups
65	}
66	
67	// search performs a v4 query-serve search across every cell that hosts the
68	// caller's in-scope repos, then merges the per-cell responses into one
69	// response. It is the semantic sibling of searchAllCells (code): resolve
70	// scope → group by hosting cell → one query-serve call per cell → tiered
71	// merge.
72	//
73	// Scope follows Config.ScopeSlugs — an explicit repo filter wins over
74	// --all-repos (the more specific filter scopes the search):
75	//   - unfiltered (repo:* / --all-repos with no explicit filter) → every cell
76	//     is queried with NO repo param, so query-serve returns everything the
77	//     caller's token authorizes there (matching the BFF and keeping the query
78	//     small for users with many repos).
79	//   - explicit repo filter(s) or the current-repo default → the slugs are
80	//     resolved via truncation-proof exact-match lookups and each cell is
81	//     scoped to the ULIDs it hosts.
82	//
83	// Completeness caveats (truncated index, failed regions) are returned as
84	// Response.Warnings for the caller to surface.
85	func (s *semanticSearchV4Session) search(ctx context.Context, cfg search.Config) (*search.Response, error) {
86		if err := search.ValidateRepoFilters(cfg.Repos); err != nil {
87			return nil, err //nolint:wrapcheck // user-facing validation message
88		}
89	
90		coreClient, err := s.client()
91		if err != nil {
92			if errors.Is(err, auth.ErrNotLoggedIn) {
93				return nil, loginHintErr(err)
94			}
95			return nil, fmt.Errorf("semantic search: resolving control-plane client: %w", err)
96		}
97	
98		slugs, allRepos := cfg.ScopeSlugs()
99		var cells []cellGroup
100		var warnings []string
101		scoped := !allRepos
102		if scoped {
103			if len(slugs) == 0 {
104				return nil, errors.New("semantic search: could not determine the repository to search")
105			}
106			entries, err := s.resolveScope(ctx, slugs)
107			if err != nil {
108				return nil, err
109			}
110			cells = groupReposByCell(entries)
111		} else {
112			index, err := s.listFullIndex(ctx)
113			if err != nil {
114				return nil, fmt.Errorf("semantic search: listing repos for cell discovery: %w", err)
115			}
116			if index.Truncated {
117				// Debug, not Warn: the user-facing channel is the Warnings entry;
118				// slog's default handler would print a Warn straight to stderr on
119				// commands that never ran logging.Init.
120				logging.Debug(ctx, "semantic search: repo index truncated; cross-repo results may be incomplete")
121				warnings = append(warnings, "repo index truncated; cross-repo results may be incomplete")
122			}
123			cells = groupReposByCell(index.Repos)
124		}
125	
126		if len(cells) == 0 {
127			return &search.Response{Results: []search.Result{}, Page: 1, Warnings: warnings}, nil
128		}
129		resolveCellBaseURLs(ctx, s.clusterClient(coreClient), cells)
130	
131		results, err := fanOutCells(ctx, s.insecureHTTP, semanticSearchV4CellTimeout, cells, func(ctx context.Context, group cellGroup, client *api.Client) (*search.Response, error) {
132			// Scoped: restrict the cell to the ULIDs it hosts. Unfiltered: send no
133			// repo param and let query-serve search everything the token
134			// authorizes in that cell (avoids per-request repo-filter caps for
135			// large accounts).
136			var repoIDs []string
137			if scoped {
138				repoIDs = group.repoIDs
139			}
140			return search.CellV4(ctx, client, cfg, repoIDs)
141		})
142		if err != nil {
143			if errors.Is(err, auth.ErrNotLoggedIn) {
144				return nil, loginHintErr(err)
145			}
146			return nil, fmt.Errorf("semantic search: %w", err)
147		}
148	
149		resp, err := mergeSemanticV4Responses(ctx, cfg.Limit, cfg.Page, results)
150		if err != nil {
151			return nil, err
152		}
153		resp.Warnings = append(warnings, resp.Warnings...)
154		return resp, nil
155	}
156	
157	// client returns the cached control-plane client, creating it on first use.
158	func (s *semanticSearchV4Session) client() (*coreapi.Client, error) {
159		s.mu.Lock()
160		defer s.mu.Unlock()
161		if s.coreClient != nil {
162			return s.coreClient, nil
163		}
164		c, err := coreapi.New()
165		if err != nil {
166			return nil, err
167		}
168		s.coreClient = c
169		return c, nil
170	}
171	
172	// listFullIndex fetches (once) and caches the caller's full repo index, used
173	// for unfiltered searches and raw-ID filter matching.
174	func (s *semanticSearchV4Session) listFullIndex(ctx context.Context) (*coreapi.ListReposOutputBody, error) {
175		s.mu.Lock()
176		defer s.mu.Unlock()
177		if s.fullIndex != nil {
178			return s.fullIndex, nil
179		}
180		reposCtx, cancel := context.WithTimeout(ctx, semanticSearchControlPlaneTimeout)
181		defer cancel()
182		index, err := s.coreClient.ListRepos(reposCtx, coreapi.ListReposParams{})
183		if err != nil {
184			return nil, err
185		}
186		s.fullIndex = index
187		return index, nil
188	}
189	
190	// resolveScope resolves explicit repo filters (or the current-repo default)
191	// to index entries, deduped by repo ID. owner/name slugs use the exact-match
192	// ListRepos filter — immune to index truncation on large accounts — while raw
193	// IDs (no slash) fall back to matching against the full index. Zero matches
194	// is a clear error; a partially matched multi-repo filter proceeds with the
195	// matches, like resolveRepoFilters does for code search.
196	func (s *semanticSearchV4Session) resolveScope(ctx context.Context, slugs []string) ([]coreapi.RepoIndexEntry, error) {
197		var entries []coreapi.RepoIndexEntry
198		seen := make(map[string]bool, len(slugs))
199		for _, f := range slugs {
200			matched, err := s.lookupFilter(ctx, f)
201			if err != nil {
202				return nil, err
203			}
204			for _, e := range matched {
205				if !seen[e.ID] {
206					seen[e.ID] = true
207					entries = append(entries, e)
208				}
209			}
210		}
211		if len(entries) == 0 {
212			return nil, fmt.Errorf("no matching repositories found for %v (is the repo mirrored to Entire?)", slugs)
213		}
214		return entries, nil
215	}
216	
217	// lookupFilter resolves one repo filter to index entries, cached per session.
218	// Matching mirrors resolveRepoFilters: a gh/ prefix is stripped, owner/name
219	// matches full_name (case-insensitive, server-side exact match), and a raw
220	// ULID matches the index entry's ID.
221	func (s *semanticSearchV4Session) lookupFilter(ctx context.Context, filter string) ([]coreapi.RepoIndexEntry, error) {
222		s.mu.Lock()
223		if cached, ok := s.slugRepos[filter]; ok {
224			s.mu.Unlock()
225			return cached, nil
226		}
227		s.mu.Unlock()
228	
229		slug := strings.TrimPrefix(filter, "gh/")
230		var matched []coreapi.RepoIndexEntry
231		if strings.Contains(slug, "/") {
232			lookupCtx, cancel := context.WithTimeout(ctx, semanticSearchControlPlaneTimeout)
233			defer cancel()
234			out, err := s.coreClient.ListRepos(lookupCtx, coreapi.ListReposParams{Filter: coreapi.NewOptString(slug)})
235			if err != nil {
236				return nil, fmt.Errorf("semantic search: resolving repository %q: %w", filter, err)
237			}
238			matched = out.Repos
239		} else {
240			// Raw repo ID — the exact-match filter only matches full_name, so
241			// match by ID against the full index.
242			index, err := s.listFullIndex(ctx)
243			if err != nil {
244				return nil, fmt.Errorf("semantic search: resolving repository %q: %w", filter, err)
245			}
246			_, matched = resolveRepoFilters([]string{filter}, index.Repos)
247		}
248	
249		s.mu.Lock()
250		if s.slugRepos == nil {
251			s.slugRepos = make(map[string][]coreapi.RepoIndexEntry)
252		}
253		s.slugRepos[filter] = matched
254		s.mu.Unlock()
255		return matched, nil
256	}
