20	// v4Ckpt builds a checkpoint result with the given id and ranking metadata.
21	// tier < 0 means "no tier field" (the ANN-only fallback shape).
22	func v4Ckpt(id string, tier int, meta search.Meta) search.Result {
23		if tier >= 0 {
24			meta.Tier = iptr(tier)
25		}
26		return search.Result{
27			Type:       search.TypeCheckpoint,
28			Meta:       meta,
29			Checkpoint: &search.CheckpointResult{ID: id},
30		}
31	}
32	
33	func v4Commit(sha string, tier int, meta search.Meta) search.Result {
34		if tier >= 0 {
35			meta.Tier = iptr(tier)
36		}
37		return search.Result{
38			Type:   search.TypeCommit,
39			Meta:   meta,
40			Commit: &search.CommitResult{CommitSHA: sha},
41		}
42	}
43	
44	// v4RepoRow builds a repo-type result via the wire format, since repo rows
45	// have no typed struct (payload lives in rawData).
46	func v4RepoRow(t *testing.T, id string, score float64) search.Result {
47		t.Helper()
48		raw := `{"type":"repo","data":{"id":"` + id + `","name":"x"},"searchMeta":{"score":` + jsonFloat(score) + `}}`
49		var r search.Result
50		if err := json.Unmarshal([]byte(raw), &r); err != nil {
51			t.Fatalf("building repo row: %v", err)
52		}
53		return r
54	}
55	
56	func jsonFloat(f float64) string {
57		b, _ := json.Marshal(f) //nolint:errcheck,errchkjson // float64 cannot fail to marshal
58		return string(b)
59	}
