61	func v4CellOK(resp *search.Response) cellCallResult[*search.Response] {
62		return cellCallResult[*search.Response]{value: resp}
63	}
64	
65	func v4CellErr(err error) cellCallResult[*search.Response] {
66		return cellCallResult[*search.Response]{err: err}
67	}
