80	// TestMergeSemanticV4Responses_TierOrdering verifies the cross-cell interleave
81	// applies query-serve's own ordering: repos first, then tier-0 by BM25 desc,
82	// tier-1 by rerank score desc, then promoted tier-2 by ANN asc — regardless of
83	// which cell each result came from.
84	func TestMergeSemanticV4Responses_TierOrdering(t *testing.T) {
85		t.Parallel()
86	
87		cellA := &search.Response{Results: []search.Result{
88			v4Ckpt("a-t1-low", 1, search.Meta{Score: 0.5}),
89			v4Ckpt("a-t0-high", 0, search.Meta{BM25Score: fptr(9.0)}),
90			// tier-2 alongside upper tiers in the same cell → promoted.
91			v4Ckpt("a-t2", 2, search.Meta{ANNScore: fptr(0.30)}),
92		}, Total: 3}
93		cellB := &search.Response{Results: []search.Result{
94			v4RepoRow(t, "repo-1", 0.9),
95			v4Ckpt("b-t0-low", 0, search.Meta{BM25Score: fptr(3.0)}),
96			v4Ckpt("b-t1-high", 1, search.Meta{Score: 0.8}),
97			v4Ckpt("b-t2", 2, search.Meta{ANNScore: fptr(0.10)}),
98		}, Total: 4}
99	
100		resp, err := mergeSemanticV4Responses(context.Background(), 0, 0, []cellCallResult[*search.Response]{
101			v4CellOK(cellA), v4CellOK(cellB),
102		})
103		if err != nil {
104			t.Fatal(err)
105		}
106	
107		want := []string{"repo-1", "a-t0-high", "b-t0-low", "b-t1-high", "a-t1-low", "b-t2", "a-t2"}
108		got := v4ResultIDs(t, resp.Results)
109		if strings.Join(got, ",") != strings.Join(want, ",") {
110			t.Errorf("merged order = %v, want %v", got, want)
111		}
112		if resp.Total != 7 {
113			t.Errorf("total = %d, want 7", resp.Total)
114		}
115		if resp.Page != 1 {
116			t.Errorf("page = %d, want 1", resp.Page)
117		}
118	}
